// Lookup: full reverse-DNS id -> 32x32 RGB565 icon, or NULL.
static inline const uint16_t *pageros_app_icon_for(const char *app_id) {
    if (!app_id) return NULL;
    if (strcmp(app_id, "news.pageros.app") == 0) return icon_news;
    if (strcmp(app_id, "email.pageros.app") == 0) return icon_email;
    if (strcmp(app_id, "maps.pageros.app") == 0) return icon_maps;
    if (strcmp(app_id, "dm.pageros.app") == 0) return icon_dm;
    if (strcmp(app_id, "drive.pageros.app") == 0) return icon_drive;
    if (strcmp(app_id, "ssh.pageros.app") == 0) return icon_ssh;
    if (strcmp(app_id, "askai.pageros.app") == 0) return icon_askai;
    if (strcmp(app_id, "stocks.pageros.app") == 0) return icon_stocks;
    if (strcmp(app_id, "wiki.pageros.app") == 0) return icon_wiki;
    if (strcmp(app_id, "translate.pageros.app") == 0) return icon_translate;
    return NULL;
}
